
/* PAUSE MENU + PHONE — replaces the accidental map/car picker path. */
(function(){
'use strict';
if(!window.GameSystems)return;
let ctx=null,pause=null,phone=null,pauseOpen=false,phoneOpen=false,screen='main',callTimer=0,phoneFocus=0;
function css(){const st=document.createElement('style');st.id='pausePhoneStyles';st.textContent=`
#gamePause,#gamePhone{position:absolute;inset:0;z-index:180;display:none;pointer-events:auto;font-family:"Segoe UI",system-ui,sans-serif}
#gamePause.open{display:flex;align-items:center;justify-content:center;background:rgba(3,5,10,.76);backdrop-filter:blur(9px)}
.pauseCard{width:min(760px,92vw);min-height:470px;border:1px solid #43506a;border-radius:22px;background:linear-gradient(145deg,#111827,#06090f);box-shadow:0 28px 100px #000;padding:28px}
.pauseCard h1{font-size:42px;letter-spacing:5px;color:#ff2d9b;margin:0 0 6px}.pauseSub{color:#8290a6;font-size:12px;letter-spacing:2px;margin-bottom:22px}
.pauseGrid{display:grid;grid-template-columns:230px 1fr;gap:22px}.pauseNav{display:flex;flex-direction:column;gap:8px}.pauseNav button,.pauseAction{min-height:46px;padding:0 15px;border:1px solid #2d394e;border-radius:10px;background:#0d1420;color:#dce7f5;text-align:left;font-weight:900;letter-spacing:1.4px;cursor:pointer}.pauseNav button:hover,.pauseNav button.on,.pauseAction:hover{border-color:#20e3ff;color:#20e3ff;background:rgba(32,227,255,.09)}
.pausePane{min-height:340px;padding:20px;border:1px solid #202b3d;border-radius:14px;background:rgba(3,7,13,.7);color:#c9d4e4;line-height:1.6}.pausePane h2{font-size:20px;letter-spacing:2px;color:#ffd23f;margin:0 0 12px}.pausePane p{margin:0 0 12px}.pausePane input[type=range]{width:100%}.pauseFoot{display:flex;justify-content:flex-end;margin-top:16px}.pauseAction{min-width:130px;text-align:center}
#gamePhone.open{display:block;inset:auto 14px 14px auto;width:328px;height:min(590px,calc(100vh - 28px));background:transparent;pointer-events:none}.phoneShell{width:310px;height:100%;border:9px solid #111722;border-radius:38px;background:#070b12;box-shadow:0 22px 90px #000;overflow:hidden;position:relative;pointer-events:auto}body:has(#gamePhone.open) #map{opacity:0;pointer-events:none}.phoneTop{height:62px;padding:19px 18px 0;background:linear-gradient(135deg,#ff2d9b,#5f2dff);font-weight:950;letter-spacing:1.5px}.phoneTime{float:right;font-size:12px}.phoneBody{height:calc(100% - 62px);padding:18px;background:linear-gradient(#0e1522,#070b12);color:#fff}.appGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:17px 10px}.app{border:0;background:none;color:#77879f;font-size:10px;text-align:center}.app i{display:flex;width:56px;height:56px;margin:0 auto 7px;border-radius:16px;align-items:center;justify-content:center;background:#202a3a;font-style:normal;font-size:25px;filter:grayscale(.7)}.app.live{color:#fff;cursor:pointer}.app.live i{background:linear-gradient(145deg,#3bff8b,#0b9d61);filter:none}.phoneList button{width:100%;min-height:58px;margin-bottom:8px;border:1px solid #26344b;border-radius:12px;background:#111a29;color:#fff;text-align:left;padding:0 14px;font-weight:800;cursor:pointer}.phoneBack{position:absolute;bottom:13px;left:50%;width:78px;height:5px;transform:translateX(-50%);border:0;border-radius:10px;background:#68768b;cursor:pointer}.phoneKeyFocus{outline:2px solid #20e3ff!important;outline-offset:2px;filter:none!important;color:#fff!important}.callScreen{text-align:center;padding-top:78px}.callAvatar{width:82px;height:82px;margin:0 auto 20px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#3bff8b;color:#04120c;font-size:38px}.callState{margin-top:12px;color:#8fa1b8;font-size:12px;letter-spacing:1px}
body.game-paused #mobileControls,body.game-paused #cbMobile,body.paint-spray-active #mobileControls{display:none!important}
@media(max-width:650px){.pauseCard{min-height:0;padding:16px}.pauseCard h1{font-size:28px}.pauseGrid{grid-template-columns:1fr}.pauseNav{display:grid;grid-template-columns:repeat(2,1fr)}.pausePane{min-height:190px}.phoneShell{transform:scale(.82)}}`;document.head.appendChild(st);}
function releaseMouse(){try{if(document.pointerLockElement)document.exitPointerLock();}catch(_){} }
function paused(v){pauseOpen=!!v;pause.classList.toggle('open',pauseOpen);document.body.classList.toggle('game-paused',pauseOpen||phoneOpen);if(v){releaseMouse();renderPause('main');}if(ctx.input.clearAll)ctx.input.clearAll(v?'pause-open':'pause-close');}
function phoneSet(v){phoneOpen=!!v;phone.classList.toggle('open',phoneOpen);document.body.classList.toggle('game-paused',pauseOpen||phoneOpen);if(v){releaseMouse();showApps();setPhoneFocus(0);}if(ctx.input.clearAll)ctx.input.clearAll(v?'phone-open':'phone-close');}
function safeReload(){if(location.protocol==='file:'&&window.top!==window.self){ctx.fx.toast('Close the preview frame and open the HTML directly','#ffd23f');return;}location.reload();}
function removeOwnFileFrames(){if(location.protocol!=='file:')return;const own=location.href.split('#')[0];for(const f of document.querySelectorAll('iframe[src]')){try{if(new URL(f.src,location.href).href.split('#')[0]===own)f.remove();}catch(_){}}}
function phoneButtons(){return phone?[...phone.querySelectorAll('.phoneBody button:not([disabled]),.phoneBack')].filter(b=>b.offsetParent!==null):[];}
function setPhoneFocus(i){const bs=phoneButtons();for(const b of bs)b.classList.remove('phoneKeyFocus');if(!bs.length){phoneFocus=0;return;}phoneFocus=(i%bs.length+bs.length)%bs.length;bs[phoneFocus].classList.add('phoneKeyFocus');try{bs[phoneFocus].focus({preventScroll:true});}catch(_){}}
function movePhoneFocus(k){const bs=phoneButtons();if(!bs.length)return;let n=phoneFocus;if(k==='arrowright')n++;else if(k==='arrowleft')n--;else if(k==='arrowdown')n+=phone.querySelector('.appGrid')?3:1;else if(k==='arrowup')n-=phone.querySelector('.appGrid')?3:1;setPhoneFocus(n);}
function pane(html){pause.querySelector('.pausePane').innerHTML=html;}
function renderPause(which){screen=which||'main';pause.querySelectorAll('.pauseNav button').forEach(b=>b.classList.toggle('on',b.dataset.page===screen));
 if(screen==='settings'){pane('<h2>SETTINGS</h2><p>Global sound can be toggled with <b>N</b>. Camera sensitivity is saved immediately.</p><div id="pauseSteerRow"><p style="margin:0 0 6px"><b style="color:#ffd23f">TOUCH STEERING</b></p><p><button class="pauseAction" data-msteer="buttons">L/R BUTTONS</button> <button class="pauseAction" data-msteer="pad">ANALOG PAD</button> <button class="pauseAction" data-msteer="swipe">SWIPE STICK</button></p></div><label>Camera sensitivity <input id="pauseSens" type="range" min="40" max="220" value="100"></label><p><button class="pauseAction" id="pauseMute">TOGGLE SOUND</button> <button class="pauseAction" id="pauseDamageNumbers">DAMAGE NUMBERS</button> <button class="pauseAction" id="pauseAdmin">ADMIN MODE</button> <button class="pauseAction" id="openAdmin">OPEN ADMIN PANEL · F10</button></p>');const sl=pause.querySelector('#pauseSens'),cam=GameSystems.api('camera'),dn=GameSystems.api('damageNumbers'),admin=GameSystems.api('admin');sl.oninput=()=>cam&&cam.setSensitivity&&cam.setSensitivity(+sl.value/100);pause.querySelector('#pauseMute').onclick=()=>{window.dispatchEvent(new KeyboardEvent('keydown',{key:'n'}));};const db=pause.querySelector('#pauseDamageNumbers'),ab=pause.querySelector('#pauseAdmin'),ob=pause.querySelector('#openAdmin'),paint=()=>{db.textContent='DAMAGE NUMBERS · '+(dn&&dn.enabled?'ON':'OFF');ab.textContent='ADMIN MODE · '+(admin&&admin.enabled()?'ON':'OFF');ob.disabled=!(admin&&admin.enabled());};db.onclick=()=>{if(dn)dn.toggle();paint();};ab.onclick=()=>{if(admin)admin.toggleEnabled();paint();};ob.onclick=()=>{paused(false);if(admin)admin.open();};paint();}
 else if(screen==='new'){pane('<h2>NEW GAME</h2><p>This clears progression, owned cars, tuning and saved preferences, then restarts in Neon State.</p><button class="pauseAction" id="confirmNew">START NEW GAME</button>');pause.querySelector('#confirmNew').onclick=()=>{const sv=GameSystems.api('save');if(sv&&sv.resetProgression)sv.resetProgression();safeReload();};}
 else if(screen==='load'){pane('<h2>LOAD GAME</h2><p>The game autosaves. Reload the latest persistent state now.</p><button class="pauseAction" id="confirmLoad">LOAD AUTOSAVE</button>');pause.querySelector('#confirmLoad').onclick=safeReload;}
 else if(screen==='controls'){const hp=GameSystems.api('help');if(hp&&hp.open){paused(false);hp.open();return;}pane('<h2>CONTROLS</h2><p>WASD move · mouse look/fire on foot · RMB aim · C camera · E enter/exit · P phone · V garage · H full controls.</p>');}
 else if(screen==='brief'){pane('<h2>BRIEF</h2><p><b>Current vehicle:</b> '+ctx.vehicles.tune.name+'</p><p><b>Location:</b> '+ctx.world.id.toUpperCase()+'</p><p><b>Wanted:</b> '+ctx.stats.wanted+' / 6</p><p>Explore the city, build drift combos, enter street races, use Paint & Spray garages to repair and evade police, and call the mechanic from Contacts when your car is stranded.</p>');}
 else pane('<h2>PAUSED</h2><p>Continue the current game, manage settings, reload your autosave, choose a map, view controls, or read the current brief.</p><p>Press <b>Escape</b> again to resume.</p>');}
function buildPause(){pause=document.createElement('div');pause.id='gamePause';pause.innerHTML='<div class="pauseCard"><h1>NEON STATE</h1><div class="pauseSub">PAUSE MENU</div><div class="pauseGrid"><div class="pauseNav"><button data-page="main">RESUME</button><button data-page="settings">SETTINGS</button><button data-page="new">NEW GAME</button><button data-page="load">LOAD GAME</button><button data-page="controls">CONTROLS</button><button data-page="brief">BRIEF</button></div><div class="pausePane"></div></div><div class="pauseFoot"><button class="pauseAction" id="pauseResume">RESUME</button></div></div>';ctx.dom.ui.appendChild(pause);pause.querySelectorAll('.pauseNav button').forEach(b=>b.onclick=()=>b.dataset.page==='main'?paused(false):renderPause(b.dataset.page));pause.querySelector('#pauseResume').onclick=()=>paused(false);}
function showApps(){const body=phone.querySelector('.phoneBody');body.innerHTML='<div class="appGrid"><button class="app live" data-app="contacts"><i>☎</i>Contacts</button><button class="app"><i>✉</i>Messages</button><button class="app"><i>▣</i>Camera</button><button class="app"><i>♪</i>Music</button><button class="app"><i>⌖</i>Maps</button><button class="app"><i>◎</i>Web</button><button class="app"><i>▦</i>Bank</button><button class="app"><i>⚙</i>Settings</button><button class="app"><i>▤</i>Jobs</button></div>';body.querySelector('[data-app=contacts]').onclick=showContacts;setTimeout(()=>setPhoneFocus(0),0);}
function showContacts(){phone.querySelector('.phoneBody').innerHTML='<h3>CONTACTS</h3><div class="phoneList"><button id="callMechanic">🔧 Mechanic<br><small>Deliver my current car</small></button><button disabled>Emergency Services</button><button disabled>Taxi</button></div>';phone.querySelector('#callMechanic').onclick=callMechanic;setTimeout(()=>setPhoneFocus(0),0);}
function mechanicPose(){
  const rg=GameSystems.api('roadgraph'),px=ctx.player.x,pz=ctx.player.z,py=ctx.player.y||0,h=ctx.player.heading||0,candidates=[];
  if(rg&&rg.randomPointOnRoads)for(let ring=22;ring<=190;ring+=28)for(let i=0;i<5;i++){const q=rg.randomPointOnRoads(px,pz,Math.max(12,ring-24),ring+24);if(q)candidates.push(q);}
  const nr=ctx.world.nearestRoad&&ctx.world.nearestRoad(px,pz);if(nr)candidates.push({x:nr.x,z:nr.z,y:nr.y,heading:nr.heading,width:nr.width});
  let best=null,bestScore=1e9;for(const q of candidates){if(!q||ctx.world.isDrowningAt(q.x,q.z,q.y||0))continue;const d=Math.hypot(q.x-px,q.z-pz);if(d<12||d>230)continue;let reachable=true;if(rg&&rg.route){const route=rg.route({x:px,z:pz,y:py},{x:q.x,z:q.z,y:q.y||py});reachable=!!(route&&route.length>=2);}if(!reachable)continue;const behind=(q.x-px)*Math.sin(h)+(q.z-pz)*Math.cos(h),score=Math.abs(d-48)+(behind>0?24:0)+Math.abs((q.y||0)-py)*.35;if(score<bestScore){best=q;bestScore=score;}}
  if(best)return{x:best.x,z:best.z,y:best.y,heading:best.heading==null?h:best.heading};
  const sp=ctx.world.active&&ctx.world.active.spawn||{x:px-Math.sin(h)*18,z:pz-Math.cos(h)*18,heading:h};return{x:sp.x,z:sp.z,y:ctx.world.groundHeightAt(sp.x,sp.z,py),heading:sp.heading||h};
}
function callMechanic(){
 const body=phone.querySelector('.phoneBody');if(!ctx.player.onFoot){body.innerHTML='<div class="callScreen"><div class="callAvatar">🔧</div><h2>MECHANIC</h2><div class="callState">EXIT YOUR VEHICLE FIRST</div></div>';return;}const prog=GameSystems.api('progression'),fac=GameSystems.api('facilities'),stored=fac&&fac.storedVehicles?fac.storedVehicles():[],current=prog.currentVehicle(),rows=[];for(const id of prog.owned()){const hp=id===current?ctx.carState.hp:100,base=250,repair=Math.max(0,Math.round((100-hp)*18/25)*25);rows.push({id,name:prog.entry(id).displayName,hp,base,repair,total:base+repair,stored:null});}for(const s of stored){const e=prog.entry(s.vehicleId);if(e)rows.push({id:s.vehicleId,name:e.displayName+' · '+s.facilityName,hp:s.hp,base:325,repair:Math.max(0,Math.round((100-s.hp)*18/25)*25),stored:s});}for(const r of rows)r.total=r.base+r.repair;body.innerHTML='<div class="callScreen"><div class="callAvatar">🔧</div><h2>PICK A DELIVERY</h2><div class="callState">FULL REPAIR INCLUDED</div><div class="mechanicList"></div></div>';const list=body.querySelector('.mechanicList');for(const r of rows){const b=document.createElement('button');b.className='phoneRow';b.innerHTML='<b>'+r.name+'</b><small>Condition '+Math.round(r.hp)+'% · delivery $'+r.base.toLocaleString()+' + repair $'+r.repair.toLocaleString()+' = $'+r.total.toLocaleString()+'</small>';b.onclick=()=>{if(!prog.spend(r.total,'mechanic-delivery:'+r.id)){ctx.fx.toast('Need $'+r.total.toLocaleString(),'#ff6b6b');return;}const p=mechanicPose();if(!p||!ctx.engine.deliverVehicle(r.id,p)){prog.credit(r.total);ctx.fx.toast('mechanic could not reach this position','#ff6b6b');return;}if(r.stored&&fac.takeStored)fac.takeStored(r.stored.facilityId,r.stored.index);ctx.carState.hp=100;ctx.engine.repairPowertrain();const vd=GameSystems.api('vdamage');if(vd)vd.repair&&vd.repair('player');body.querySelector('.callState').textContent='DELIVERED · FULLY REPAIRED';ctx.fx.toast(r.name+' delivered · $'+r.total.toLocaleString(),'#3bff8b');};list.appendChild(b);}if(!rows.length)list.textContent='NO OWNED OR STORED VEHICLES';
}
function buildPhone(){phone=document.createElement('div');phone.id='gamePhone';phone.innerHTML='<div class="phoneShell"><div class="phoneTop">NEON<span class="phoneTime">01:11</span></div><div class="phoneBody"></div><button class="phoneBack" aria-label="Back"></button></div>';ctx.dom.ui.appendChild(phone);phone.querySelector('.phoneBack').onclick=()=>phoneSet(false);phone.addEventListener('click',()=>setTimeout(()=>setPhoneFocus(0),0));showApps();}
GameSystems.register({id:'pausephone',order:97,alwaysUpdate:true,init(c){ctx=c;css();removeOwnFileFrames();buildPause();buildPhone();const help=GameSystems.api('help');if(help)help.addControls('PHONE & MENU',[['P','Open phone'],['Arrows + Enter','Navigate phone'],['Esc','Close / pause menu']]);},onKey(k){
  if(k==='p'&&ctx.engine.started&&!ctx.engine.selectionOpen){phoneSet(!phoneOpen);return true;}
  if(phoneOpen){if(k==='escape'){phoneSet(false);return true;}if(k==='arrowup'||k==='arrowdown'||k==='arrowleft'||k==='arrowright'){movePhoneFocus(k);return true;}if(k==='enter'){const bs=phoneButtons(),b=bs[phoneFocus];if(b)b.click();return true;}return true;}
  if(k==='escape'&&ctx.engine.started&&!ctx.engine.selectionOpen){paused(!pauseOpen);return true;}return pauseOpen;
},update(){if((pauseOpen||phoneOpen)&&ctx.player.dead){paused(false);phoneSet(false);}},api:{openPause(){if(!pauseOpen)paused(true);},closePause(){paused(false);},openPhone(){phoneSet(true);},closePhone(){phoneSet(false);},get pauseOpen(){return pauseOpen;},get phoneOpen(){return phoneOpen;},get open(){return pauseOpen||phoneOpen;}}});
})();
